      "「閉める」是他動詞，「〜ている」在這裡容易被理解為「某人正在關門的動作」，而非「門本身呈現關閉的狀態」。",
      "「閉まる」是自動詞，＋ています表示「現在呈現關閉的狀態」＝門是關著的，正解。",
      "「〜てある」通常只接在他動詞後面表示人為造成的狀態，「閉まる」是自動詞，不能這樣接續。"
